content.text:
{
  "results": [
    {
      "server": "atuin",
      "tools": [
        {
          "tool_name": "atuin__atuin_history",
          "description": "Search the user's shell history, recorded by Atuin across all their terminal sessions and machines. Each result includes the command, timestamp, working directory, exit code, duration, and a history ID; commands run by AI agents carry the agent's name and stated intent. Set only_failed: true when investigating failures, and authors: [\"$all-agent\"] to see what agents ran. Pass a history ID to atuin_output to read what the command printed.",
          "score": 25.979814529418945,
          "input_schema": {
            "type": "object",
            "properties": {
              "query": {
                "type": "string",
                "description": "Search query matched against past commands: commands containing every term come first, then fuzzy matches (each term's letters in order) fill the rest. Prefer a few distinctive terms (e.g. 'ffmpeg av1'), not a sentence; terms are AND-ed. An empty string returns the most recent commands. Supports fzf-style operators per space-separated term: ^prefix, suffix$, 'exact-substring, !negate, and r/regex/."
              },
              "filter_modes": {
                "type": "array",
                "items": {
                  "type": "string",
                  "enum": [
                    "global",
                    "host",
                    "session",
                    "directory",
                    "workspace"
                  ]
                },
                "description": "Optional search scope; the first entry is used and the default is 'global' (all history). 'workspace' limits to commands run inside the current repository, git or Jujutsu, 'directory' to the exact current working directory, 'host' to this machine, 'session' to the shell session that launched this server (errors when it was not launched from a shell). Start global and narrow only if results are noisy."
              },
              "limit": {
                "type": "integer",
                "minimum": 1,
                "maximum": 50,
                "default": 10,
                "description": "Maximum number of results."
              },
              "only_failed": {
                "type": "boolean",
                "default": false,
                "description": "Only return commands that recorded a non-zero exit code. Commands still running (no exit recorded yet) are excluded."
              },
              "authors": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "Filter by who ran the command: '$all-user' for human-run commands, '$all-agent' for commands run by AI agents, or any literal author name (well-known agents: amp, claude-code, codex, copilot, grok, kiro, omp, opencode, pi). Multiple entries are OR-ed. Omit for everything."
              }
            },
            "required": [
              "query"
            ]
          }
        },
        {
          "tool_name": "atuin__atuin_output",
          "description": "Read the terminal output that a previously executed command actually printed, identified by a history ID from atuin_history results. Use it to see an error exactly as the user saw it, or to re-read the output of an expensive or side-effectful command without re-running it. Output capture requires the Atuin daemon; output is only available for recent commands captured while the daemon was running.",
          "score": 24.093435287475586,
          "input_schema": {
            "type": "object",
            "properties": {
              "history_id": {
                "type": "string",
                "description": "The history entry ID (UUID), as returned by atuin_history."
              },
              "ranges": {
                "type": "array",
                "items": {
                  "type": "array",
                  "items": {
                    "type": "integer"
                  },
                  "minItems": 2,
                  "maxItems": 2
                },
                "description": "Optional [start, end] line ranges to fetch (0-based, end-inclusive). Negative indices count from the end of the output, e.g. [[-80, -1]] is the last 80 lines — fetch that first when investigating a failure, since errors usually print at the end. Defaults to the full output."
              }
            },
            "required": [
              "history_id"
            ]
          }
        },
        {
          "tool_name": "atuin__atuin_threads_search",
          "description": "Full-text search across the transcripts of the threads (AI coding-agent sessions) Atuin has captured (Claude Code, Codex, opencode, pi). Reach for it when a task points at earlier work ('again', 'still', 'continue', a known issue, what was decided): a previous agent may already have diagnosed or decided it. Finds which thread discussed a topic, hit an error, touched a file, or made a decision — it searches what the user and agent wrote, tool names, and thread titles. Each result gives the thread id, harness, last-active time, title, directory, and the best matching message's number and snippet; pass the id to atuin_threads_read to read around the match. Requires the Atuin daemon with thread capture enabled.",
          "score": 21.632394790649414,
          "input_schema": {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "title": "AtuinThreadsSearchToolCall",
            "type": "object",
            "properties": {
              "terms": {
                "description": "What to look for across captured AI-agent session transcripts (what the user and agent\nwrote, the names of tools used, and session titles), case-insensitive. Sessions with a\nmessage containing every term rank first; if there are none, sessions matching any term\n(as a prefix) are returned instead, and the result says so. The words of one term match\nonly together and in that order, so give each word its own term unless they must be\nadjacent. Use a few distinctive words, e.g. a file name, error text or identifier, not a\nsentence.",
                "type": "array",
                "items": {
                  "type": "string",
                  "minLength": 1
                },
                "minItems": 1
              },
              "limit": {
                "description": "Maximum number of sessions to return, most relevant first.",
                "type": "integer",
                "minimum": 1,
                "maximum": 20,
                "default": 5
              },
              "harness": {
                "description": "Restrict the search to sessions from one AI harness. Omit to search every harness.",
                "anyOf": [
                  {
                    "$ref": "#/$defs/HarnessArg"
                  },
                  {
                    "type": "null"
                  }
                ]
              },
              "cwd": {
                "description": "Only sessions whose working directory is this path or inside it. Relative paths,\nincluding '.', resolve against the current project directory. The result says how many\nmatches the filter left out, and where.",
                "type": [
                  "string",
                  "null"
                ],
                "default": null
              },
              "include_subagents": {
                "description": "Include subagent sessions (spawned by another agent session to do part of its work). Off\nby default: their prompts are written by the agent that spawned them, so they crowd out\nthe sessions a person ran.",
                "type": "boolean",
                "default": false
              },
              "roles": {
                "description": "Match only messages from these roles: 'user' (what the person wrote), 'assistant' (the\nagent's replies and tool calls), 'tool' (tool output), 'harness' (context the harness\ninjected). [\"user\"] finds what people asked for and corrected. Omit for every role.",
                "type": [
                  "array",
                  "null"
                ],
                "items": {
                  "$ref": "#/$defs/RoleArg"
                }
              }
            },
            "additionalProperties": false,
            "required": [
              "terms"
            ],
            "$defs": {
              "HarnessArg": {
                "description": "A harness named on the command line (`--harness`, `--in`) or in an MCP tool call, so every\nplace that takes one accepts the same names: the ones [`harness_name`] shows, with `claude`\nas a hidden synonym of `claude-code`.\n\nOnly harnesses a capture path can actually produce are offered (see `AnyHarness`): advertising\none without a capture source would return empty for every query.",
                "type": "string",
                "enum": [
                  "claude-code",
                  "codex",
                  "copilot",
                  "grok",
                  "kiro",
                  "opencode",
                  "pi",
                  "omp",
                  "amp"
                ]
              },
              "RoleArg": {
                "description": "Who a message is from, as `roles` filters it.",
                "type": "string",
                "enum": [
                  "user",
                  "assistant",
                  "tool",
                  "harness"
                ]
              }
            }
          }
        }
      ]
    }
  ],
  "total_hidden_tools": 334,
  "status": "ready",
  "note": null
}

