content.text:
{
  "results": [
    {
      "server": "atuin",
      "tools": [
        {
          "tool_name": "atuin__atuin_threads_read",
          "description": "Read a captured thread's transcript, a page of messages at a time: what the user asked, what the agent replied, and which tools it used. Capture keeps the conversation, not tool arguments or output, so runs of tool calls appear as one line of tool names. Messages are numbered; page with start (negative counts from the end, e.g. -10 for how the thread ended) and limit. Pages abridge long messages; read one message (limit: 1) to see it in full; one over 20,000 characters comes in parts, each giving the offset to read the next from. To find where something was said in a long thread, pass query (only messages with every word) or roles (['user'] for what the person said) instead of paging through it. Takes a thread id or unique prefix from atuin_threads_list or atuin_threads_search, or 'latest'.",
          "score": 1.0,
          "input_schema": {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "title": "AtuinThreadsReadToolCall",
            "type": "object",
            "properties": {
              "session_id": {
                "description": "The session to read: a full session id or atuin id, or a unique prefix of one, as returned by\natuin_threads_list or atuin_threads_search. 'latest' reads the most recent session\nbefore this one.",
                "type": "string",
                "minLength": 1
              },
              "start": {
                "description": "Message number to start from (0-based). Negative values count back from the end over\nmessages with content, so -10 shows the last ten things said. To see a search hit in\ncontext, start a few messages before its message number. Numbers count every row the\nharness recorded, including ones with nothing to read, so they run past the message count\natuin_threads_list gives; to reach the end, use a negative start.",
                "type": "integer",
