                "default": 0
              },
              "limit": {
                "description": "Maximum number of messages to show. Long messages and harness-injected context are\nabridged on a multi-message page; read a single message (limit: 1) to see it in full.",
                "type": "integer",
                "minimum": 1,
                "maximum": 200,
                "default": 40
              },
              "offset": {
                "description": "With limit: 1, where to start within the message, in characters. A message longer than\n20,000 characters comes in parts, each ending with the offset to read the next from.\nIgnored on multi-message pages.",
